1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
6	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
7	import tools.jackson.databind.node.ObjectNode;
8	
9	/** problem-json: rejections return an RFC7807 application/problem+json body with a 'status'
10	 * member equal to the HTTP status. Assert the exact content type and status value. */
11	class AcceptanceTest extends AcceptanceBase {
12	
13		@Test
14		void coreRejectionIsProblemJson() throws Exception {
15			ObjectNode o = structuredOwner();
16			o.remove("city");
