/**
 * Thrown when a create-owner request produces an identityKey (normalized telephone {@code '|'} email
 * {@code '|'} householdId) that exactly matches an existing owner's. Consolidates the former
 * telephone, email and household conflict checks. Handled globally by
 * {@link OwnerIdentityConflictExceptionHandler}, which responds 409.
 */
public class OwnerIdentityConflictException extends Exception {

    public OwnerIdentityConflictException(String identityKey) {
        super("Owner already exists with identityKey: " + identityKey);
    }
}
=== OwnerCityCapacityException ===
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request targets a city that has already reached capacity — it already
 * contains 50 or more owners. Handled globally by {@link OwnerCityCapacityExceptionHandler}, which
 * responds 409.
 */
public class OwnerCityCapacityException extends Exception {

    public OwnerCityCapacityException(String city, int count) {
        super("City is at capacity (" + count + " owners): " + city);
    }
}
=== OwnerDailyLimitException ===
package org.springframework.samples.petclinic.rest.escalation;

import java.time.LocalDate;

/**
 * Thrown when a create-owner request exceeds the daily sign-up limit — 100 or more owners have
 * already been created today (by registration date). Handled globally by
 * {@link OwnerDailyLimitExceptionHandler}, which responds 429 Too Many Requests.
 */
public class OwnerDailyLimitException extends Exception {

    public OwnerDailyLimitException(LocalDate date, int count) {
        super("Daily owner creation limit reached (" + count + " owners on " + date + ")");
    }
}

